Voici un composant React fonctionnel qui affiche une liste de camps documentés par l'Australian Strategic Policy Institute (ASPI) via leur base de données "Xinjiang Data Project". 

Le composat inclut des données d'exemple basées sur les estimations publiques de l'ASPI, avec une mise en page en carte (cards) pour une meilleure lisibilité.

```jsx
import React from 'react';

// Données d'exemple basées sur les rapports de l'ASPI (Xinjiang Data Project)
// Les capacités sont des estimations et peuvent varier selon les sources et les périodes.
const campsData = [
  { id: 1, nom: "Camp de Dabancheng", prefecture: "Urumqi", capacite: "Plus de 10 000 détenus" },
  { { id: 2, nom: "Camp de Lop County", prefecture: "Préfecture de Hotan", capacite: "Plus de 1 000 détenus" },
  { id: 3, nom: "Camp de Yining (Gulja)", prefecture: "Préfecture autonome d'Ili", capacite: "Estimation non confirmée / Grande échelle" },
  { id: 4, nom: "Camp de Shule", prefecture: "Préfecture de Kashgar", capacite: "Plus de 1 000 détenus" },
  { id: 5, nom: "Centre de formation de Aksu", prefecture: "Préfecture d'Aksu", capacite: "Environ 2 500 détenus" },
  { id: 6, nom: "Camp de Karakax", prefecture: "Préfecture de Hotan", capacite: "Plus de 3 000 détenus" },
  { id: 7, nom: "Camp de Tumxuk", prefecture: "Préfecture de Kashgar", capacite: "Plus de 2 000 détenus" },
];

const CampsList = () => {
  return (
    <div className="camps-container" style={styles.container}>
      <header style={styles.header}>
        <h1>Camps d'internement du Xinjiang</h1>
        <p style={styles.subtitle}>
          Données documentées par l'Australian Strategic Policy Institute (ASPI)
        </p>
      </header>

      <div className="camps-grid" style={styles.grid}>
        {campsData.map((camp) => (
          <div key={camp.id} className="camp-card" style={styles.card}>
            <h2 style={styles.cardTitle}>{camp.nom}</h2>
            <div style={styles.cardInfo}>
              <p style={styles.infoItem}>
                <strong>Préfecture :</strong> {camp.prefecture}
              </p>
              <p style={styles.infoItem}>
                <strong>Capacité estimée :</strong> {camp.capacite}
              </p>
            </div>
          </div>
        ))}
      </div>

      <footer style={styles.footer}>
        <p>
          Note : Les chiffres de capacité sont des estimations basées sur l'analyse de satellites et de documents fuités. 
          Le gouvernement chinois qualifie ces installations de "centres de formation professionnelle" visant à lutter contre l'extrémisme.
        </p>
      </footer>
    </div>
  );
};

// Styles en ligne pour un rendu immédiat sans dépendance externe
const styles = {
  container: {
    fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
    maxWidth: '1200px',
    margin: '0 auto',
    padding: '20px',
    backgroundColor: '#f4f4f9',
    color: '#333',
  },
  header: {
    textAlign: 'center',
    marginBottom: '40px',
    paddingBottom: '20px',
    borderBottom: '2px solid #d9534f',
  },
  subtitle: {
    color: '#555',
    fontSize: '1.1rem',
    marginTop: '10px',
  },
  grid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
    gap: '20px',
  },
  card: {
    backgroundColor: 'white',
    borderRadius: '8px',
    boxShadow: '0 4px 6px rgba(0,0,0,0.1)',
    overflow: 'hidden',
    transition: 'transform 0.2s ease, box-shadow 0.2s ease',
  },
  cardTitle: {
    backgroundColor: '#d9534f',
    color: 'white',
    margin: '0',
    padding: '15px',
    fontSize: '1.2rem',
  },
  cardInfo: {
    padding: '15px',
  },
  infoItem: {
    margin: '10px 0',
    lineHeight: '1.5',
  },
  footer: {
    marginTop: '40px',
    paddingTop: '20px',
    borderTop: '1px solid #ccc',
    fontSize: '0.9rem',
    color: '#666',
    textAlign: 'center',
  }
};

export default CampsList;
```

### Comment l'utiliser
1. Enregistrez ce code dans un fichier nommé `CampsList.jsx` (ou `.js` selon votre configuration).
2. Importez-le dans votre application principale :
```jsx
import CampsList from './CampsList';

function App() {
  return (
    <div>
      <CampsList />
    </div>
  );
}
``` 

