    display: inline-block; font-size: 11px; padding: 1px 8px;
    border-radius: 10px; margin-left: 8px; vertical-align: middle;
  }
  .tag.red { background: rgba(192,57,43,.15); color: #e07b6f; }
  .tag.gold { background: rgba(201,162,39,.15); color: #d9bc5e; }
