  .event.major {
    border-left: 5px solid var(--accent);
  }
  .event.major::before { width: 16px; height: 16px; left: -2.06rem; }

  /* Casualties section */
  .casualties {
    background: #fdf6f4;
    border: 1px solid #e5c9c2;
    border-radius: 8px;
    padding: 1.5rem 1.6rem;
