        .event {
            position: relative;
            margin-bottom: 30px;
            padding: 15px 20px;
            background: #fafafa;
            border-left: 3px solid #8b0000;
            border-radius: 0 5px 5px 0;
        }

        .event::before {
            content: '';
            position: absolute;
            left: -26px;
            top: 20px;
            width: 12px;
            height: 12px;
            background: #8b0000;
            border-radius: 50%;
            border: 2px solid white;
        }

        .date {
            font-weight: bold;
            color: #8b0000;
            font-size: 16px;
            margin-bottom: 5px;
        }

        .title {
            font-weight: bold;
            font-size: 17px;
            margin-bottom: 8px;
            color: #1a1a1a;
        }

        .desc {
            color: #555;
            font-size: 14px;
        }

        .casualties {
            background: #fff5f5;
            border: 1px solid #ffcccc;
            padding: 20px;
            margin-top: 30px;
            border-radius: 5px;
        }

        .casualties h3 {
            color: #8b0000;
            margin-bottom: 15px;
            font-size: 18px;
        }

        .casualties ul {
            list-style: none;
            padding-left: 0;
        }

        .casualties li {
            margin-bottom: 10px;
            padding-left: 20px;
            position: relative;
        }

        .casualties li::before {
            content: '•';
            position: absolute;
            left: 5px;
            color: #8b0000;
        }

        .note {
