  }

  .intro strong { color: var(--ink); font-weight: 600; }

  /* ---------- Timeline ---------- */
  .timeline-section {
    max-width: 860px;
    margin: 0 auto;
    padding: 1rem 1.5rem 4rem;
  }

  .section-title {
    font-family: var(--serif);
    font-size: 1.6rem;
    font-weight: 400;
    text-align: center;
    margin-bottom: 2.5rem;
    letter-spacing: 0.03em;
  }

  .section-title::after {
    content: "";
    display: block;
    width: 48px;
    height: 2px;
    background: var(--accent);
    margin: 0.9rem auto 0;
  }

  .timeline {
    position: relative;
  }

  .timeline::before {
    content: "";
    position: absolute;
    left: 50%;
    top: 0;
    bottom: 0;
