    transition: opacity 0.7s ease, transform 0.7s ease;
  }

  .event.visible {
    opacity: 1;
    transform: translateY(0);
  }

  .event:nth-child(odd)  { left: 0; text-align: right; }
  .event:nth-child(even) { left: 50%; text-align: left; }

  .event::before {
    content: "";
    position: absolute;
